const groupLogsByType = (
  rawLogs: T.BuildLog[],
  filterType: FilterState
): FilteredLog[] => {
  const logs = rawLogs.map((l, index) => ({ ...l, index }));

  if (filterType === 'all' || logs.length === 0) {
    return [{ hidden: false, logs }];
  }

  const groups: FilteredLog[] = [];
  let currentGroup: { type: FilterState; logs: BuildLogWithIndex[] } = {
    type: 'all',
    logs: []
  };

  for (const log of logs) {
    const logType = log.error ? 'errors' : log.warning ? 'warnings' : 'all';
    if (logType !== currentGroup.type) {
      groups.push({ hidden: currentGroup.type !== filterType, logs: currentGroup.logs });
      currentGroup = { type: logType, logs: [log] };
    } else {
      currentGroup.logs.push(log);
    }
  }

  const compactedGroups = groups.reduce((prev, cur) => {
    if (prev.at(-1)?.hidden === cur.hidden) {
      prev.at(-1)?.logs.push(...cur.logs);
      return prev;
    }
    return [...prev, cur];
  }, []);

  return compactedGroups;
};
```
