  id INTEGER PRIMARY KEY,
  username VARCHAR(255) NOT NULL
);

CREATE INDEX idx_username ON users (username);

-- Function to perform binary search
CREATE OR REPLACE FUNCTION binary_search(username TEXT)
RETURNS BOOLEAN AS $$
DECLARE
  low INTEGER := 1;
  high INTEGER := (SELECT COUNT(*) FROM users);
  mid INTEGER;
  found BOOLEAN;
BEGIN
  WHILE low <= high LOOP
