func handler(ctx context.Context) (interface{}, error) {
	region := "your-region" // Replace with your region
	sess, err := session.NewSession(&aws.Config{Region: aws.String(region)}, nil)
	if err != nil {
		log.Fatal(err)
	}
	ec2Svc := ec2.New(sess)

	// List all EBS snapshots with the "backup_type" tag
	params := &ec2.DescribeSnapshotsInput{
		Filters: []*ec2.Filter{
			{
				Name:   aws.String("tag:backup_type"),
				Values: []*string{"monthly", "daily", "weekly", "yearly"},
			},
		},
	}
	snapshots, err := ec2Svc.DescribeSnapshots(params)
	if err != nil {
		log.Fatal(err)
	}

	// Process each snapshot
	for _, snapshot := range snapshots.Snapshots {
		backupType := *snapshot.Tags[0].Value
		switch backupType {
		case "monthly":
			// Keep the last 14 monthly snapshots
			if len(snapshots.Snapshots) > 14 {
				ec2Svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{
					SnapshotId: aws.String(*snapshot.SnapshotId),
				})
