SNAKE_COLOR = (0, 0, 255)
BGCOLOR = (0, 0, 0)
FRUIT_COLOR = (255, 0, 0)
GHOST_COLOR = (255, 255, 0)

class Snake:
    def __init__(self):
        self.body = [(WIDTH // 2, HEIGHT // 2)]
        self.direction = (1, 0)

    def move(self):
        head = self.body[0]
        new_head = (
            head[0] + self.direction[0],
            head[1] + self.direction[1],
        )
        self.body.insert(0, new_head)

        if len(self.body) > 3:
            self.body.pop()

    def draw(self, screen):
        for pos in self.body:
            pygame.draw.rect(
                screen,
                SNAKE_COLOR,
                (pos[0], pos[1], 10, 10),
            )

    def check_collision(self):
        head = self.body[0]
        if head in self.body[1:]:
            return True
        if head[0] < 0 or head[0] >= WIDTH or head[1] < 0 or head[1] >= HEIGHT:
            return True
        return False


class Fruit:
    def __init__(self):
        self.pos = (random.randint(0, WIDTH - 10) // 10 * 10, random.randint(0, HEIGHT - 10) // 10 * 10)

    def draw(self, screen):
        pygame.draw.rect(
            screen,
            FRUIT_COLOR,
            (self.pos[0], self.pos[1], 10, 10),
        )


class Ghost:
    def __init__(self):
        self.pos = (random.randint(0, WIDTH - 10) // 10 * 10, random.randint(0, HEIGHT - 10) // 10 * 10)

    def draw(self, screen):
        pygame.draw.rect(
            screen,
            GHOST_COLOR,
            (self.pos[0], self.pos[1], 10, 10),
        )


def main():
    pygame.init()
    screen = pygame.display.set_mode((WIDTH, HEIGHT))
    clock = pygame.time.Clock()

    snake = Snake()
    fruit = Fruit()
    ghost = Ghost()
    score = 0

    while True:
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                pygame.quit()
                sys.exit()
            elif event.type == pygame.KEYDOWN:
                if event.key == pygame.K_LEFT and snake.direction != (1, 0):
                    snake.direction = (-1, 0)
                elif event.key == pygame.K_RIGHT and snake.direction != (-1, 0):
                    snake.direction = (1, 0)
                elif event.key == pygame.K_UP and snake.direction != (0, 1):
                    snake.direction = (0, -1)
                elif event.key == pygame.K_DOWN and snake.direction != (0, -1):
                    snake.direction = (0, 1)

        snake.move()

        if snake.body[0] == fruit.pos:
            score += 1
            fruit = Fruit()
        elif snake.body[0] == ghost.pos:
            print("Game Over! Your score is:", score)
            pygame.quit()
            sys.exit()
            break

        screen.fill(BGCOLOR)
        snake.draw(screen)
        fruit.draw(screen)
        ghost.draw(screen)
        pygame.display.flip()

        clock.tick(SPEED)


if __name__ == "__main__":
